// Heat Transfer Calculation (Conduction)
// Q = (k * A * (T_hot - T_cold)) / d
// k = Thermal conductivity (W/m·K)
// A = Surface area (m²), d = thickness (m)
const conductionHeatGain = (k: number, area: number, deltaT: number, thickness: number) => {
  return (k * area * deltaT) / thickness; // Watts (Joules/sec)
};
// Low-E double glazing drops k from 1.0 (standard glass) down to 0.15 W/m·K

// Coefficient of Performance (COP)
// COP = Useful Cooling Provided (kW) / Electrical Work Consumed (kW)
// Individual window AC: COP ≈ 2.2
// Modern District Cooling Plant: COP ≈ 6.5+ (Nearly 3x more efficient!)

// Solar Power Output Formula
// Power (W) = Solar Irradiance (W/m²) * Area (m²) * Panel Efficiency * Performance Ratio
const solarOutput = (irradiance: number, areaM2: number, efficiency: number, pr: number = 0.8) => {
  return irradiance * areaM2 * efficiency * pr;
};
// Dubai peak sun: 1000 W/m² on 20m² rooftop panels at 22% efficiency:
console.log(solarOutput(1000, 20, 0.22)); // 3,520 Watts (3.52 kW DC output)

// Temperature Degradation Calculation
// P_actual = P_rated * [1 + tempCoeff * (T_cell - 25°C)]
const tempDegradation = (pRated: number, tCell: number, tempCoeff = -0.004) => {
  return pRated * (1 + tempCoeff * (tCell - 25));
};
// At 65°C desert midday panel temp: 400W panel produces 336W (16% thermal loss)

// van 't Hoff's Formula for Osmotic Pressure:
// Pi = i * M * R * T
// i: van 't Hoff factor (for NaCl ≈ 1.9)
// M: Molarity of salt ions (mol/L)
// R: Ideal gas constant (0.08314 L·bar/mol·K)
// T: Absolute temperature in Kelvin (273.15 + C)

// Specific Energy Consumption (SEC)
// Thermal Desalination (MSF): ~12-15 kWh/m³
// Modern SWRO with Pressure Exchanger: ~2.8-3.2 kWh/m³
// Energy savings: > 75% reduction in carbon footprint

// Strouhal Number & Vortex Frequency
